/* onboarding checklist */
.ob{max-width:400px}
.ob-head{display:flex;align-items:center;gap:14px;padding:16px;border-bottom:1px solid var(--line)}
.ob-ring{position:relative;width:44px;height:44px;flex:none}
.ob-ring svg{width:100%;height:100%;transform:rotate(-90deg)}
.ob-ring circle{fill:none;stroke-width:4}
.ob-ring .bg{stroke:var(--line)}
.ob-ring .fg{stroke:var(--accent);transition:stroke-dashoffset .7s var(--ease)}
.ob-ring span{position:absolute;inset:0;display:grid;place-items:center;font-family:var(--mono);font-size:11px;font-weight:700}
.ob-head .t{font-size:15px;font-weight:600}
.ob-head .d{margin-top:2px;font-size:12.5px;color:var(--muted)}
.ob-list{padding:6px 8px 8px}
.ob-s{padding:8px}
.ob-sh{display:flex;align-items:center;gap:10px;width:100%;text-align:left;font-size:13.5px;font-weight:500;color:var(--text)}
.ob-ck{width:20px;height:20px;flex:none;display:grid;place-items:center;border:1.5px solid var(--icon-line);border-radius:50%;color:#fff;transition:background-color .3s,border-color .3s}
.ob-ck .ms{font-size:12px;opacity:0;transform:scale(.5);transition:opacity .2s,transform .35s cubic-bezier(.34,1.56,.64,1)}
.ob-s.done .ob-ck{background:var(--success);border-color:var(--success)}
.ob-s.done .ob-ck .ms{opacity:1;transform:none}
.ob-s.done .ob-sh .t{color:var(--muted);text-decoration:line-through}
.ob-sh .chev{margin-left:auto;color:var(--muted);transition:transform .4s var(--ease)}
.ob-s.open .ob-sh .chev{transform:rotate(180deg)}
.ob-bd{padding:6px 0 4px 30px;font-size:13px;line-height:1.5;color:var(--text-dim)}
.ob-bd .btn{margin-top:10px}
.ob-done{display:flex;flex-direction:column;align-items:center;gap:6px;padding:28px 16px;text-align:center}
.ob-done .nbox{color:var(--success);margin-bottom:6px}

/* ---------- onboarding checklist ---------- */
{
  const ob = $('#ob');
  const steps = [
    ['Create your workspace','Name it and pick a URL your team will remember.','Create workspace'],
    ['Connect your design file','Link Figma so the agent can read your frames.','Connect Figma'],
    ['Invite your team','Bring in the people who review and ship.','Invite people'],
    ['Run your first task','Ask the agent to audit a page and see what it finds.','Run a task'],
    ['Turn on weekly reports','Get a short summary of every run each Monday.','Turn on']
  ];
  let done = [true, false, false, false, false], open = 1;
  const R = 18, C = 2 * Math.PI * R;
  function build(first){
    const n = done.filter(Boolean).length;
    if (n === steps.length){
      morph(ob, () => { ob.innerHTML = `<div class="ob-done enter"><span class="nbox">${ic('check_circle','icon-in')}</span><div style="font-weight:600;font-size:15px">You are all set</div><div style="font-size:13px;color:var(--text-dim)">Every setup step is done. The agent is ready.</div><button class="btn" id="ob-reset" style="margin-top:10px">Start over</button></div>`; $('#ob-reset').addEventListener('click', () => { done = [true, false, false, false, false]; open = 1; Sound.play('tab'); build(); }); });
      return;
    }
    const put = () => {
      ob.innerHTML = `<div class="ob-head"><div class="ob-ring"><svg viewBox="0 0 44 44"><circle class="bg" cx="22" cy="22" r="${R}"/><circle class="fg" cx="22" cy="22" r="${R}" stroke-dasharray="${C}" stroke-dashoffset="${C}"/></svg><span>${n}/${steps.length}</span></div><div><div class="t">Get started</div><div class="d">${steps.length - n} steps left to finish setup</div></div></div>
        <div class="ob-list">${steps.map((s, i) => `<div class="ob-s ${done[i] ? 'done' : ''} ${open === i ? 'open' : ''}" data-i="${i}"><button class="ob-sh"><span class="ob-ck">${ic('check','sm')}</span><span class="t">${s[0]}</span><span class="ms sm chev">expand_more</span></button><div class="unfold ${open === i ? 'open' : ''}"><div class="uf"><div class="ob-bd">${s[1]}${done[i] ? '' : `<div><button class="btn primary" data-go="${i}">${s[2]}</button></div>`}</div></div></div></div>`).join('')}</div>`;
      requestAnimationFrame(() => requestAnimationFrame(() => { const fg = $('.fg', ob); if (fg) fg.style.strokeDashoffset = C * (1 - n / steps.length); }));
    };
    first ? put() : morph(ob, put);
  }
  ob.addEventListener('click', e => {
    const go = e.target.closest('[data-go]');
    if (go){ const i = +go.dataset.go; done[i] = true; Sound.play('done'); const nx = done.findIndex(d => !d); open = nx; setTimeout(() => build(), 350); $(`.ob-s[data-i="${i}"]`, ob).classList.add('done'); return; }
    const h = e.target.closest('.ob-sh'); if (!h) return; const i = +h.parentElement.dataset.i;
    open = open === i ? -1 : i; Sound.play(open === i ? 'open' : 'close');
    $$('.ob-s', ob).forEach(s => { const on = +s.dataset.i === open; s.classList.toggle('open', on); s.querySelector('.unfold').classList.toggle('open', on); });
  });
  build(true);
}
